export function hasProtocolGlyph(id: string): boolean {
  return id in GLYPHS;
}

/** The raw glyph geometry for a protocol id, or `undefined` when none is
 *  defined yet — the same lookup `hasProtocolGlyph`/`ProtocolGlyph` make, just
 *  handed back as data. `GLYPHS` already carries the `-base` aliasing itself
 *  (a second deployment's id points at the same `Glyph` constant its parent
 *  uses, e.g. `"aave-v3-base": AAVE_V3_MARK`), so no id-rewriting happens here.
 *  For a surface that has no "currentColor" text context to inherit from — the
 *  share-card renderer runs through satori, off the page entirely — drawing
 *  the geometry needs the fill named explicitly, which is what this exists
 *  for; `ProtocolGlyph` covers every in-app surface already. */
export function protocolGlyph(id: string): Glyph | undefined {
  return GLYPHS[id];
}

/** The monochrome glyph when one exists, else the colour PNG — the glyph-or-img
 *  fallback pattern, packaged so surfaces don't
 *  each re-implement it. `id` is the `protocols.ts` id / glyph key. A
 *  `fallback` glyph key draws in place of the PNG where `id` has no glyph:
 *  the timeline bar passes `route`, so a product without its glyph yet still
 *  draws a monochrome mark. */
export function ProtocolIcon({
  id,
  className = "",
  fallback,
}: {
  id: string;
  className?: string;
  fallback?: string;
}): ReactNode {
  if (hasProtocolGlyph(id)) return <ProtocolGlyph id={id} className={className} />;
  if (fallback && hasProtocolGlyph(fallback)) return <ProtocolGlyph id={fallback} className={className} />;
  // eslint-disable-next-line @next/next/no-img-element
  return <img src={protocolIconSrc(id)} alt="" className={`${className} rounded-[3px]`} />;
}

export function ProtocolGlyph({ id, className = "" }: { id: string; className?: string }): ReactNode {
  const glyph = GLYPHS[id];
  if (!glyph) return null;
  const geometry = (
    <>
      {glyph.paths?.map((p, i) => (
        <path key={`p${i}`} d={p.d} fillRule={p.fillRule} opacity={p.opacity} />
      ))}
      {glyph.rects?.map((r, i) => (
        <rect key={`r${i}`} x={r.x ?? 0} y={r.y ?? 0} width={r.width} height={r.height} />
      ))}
    </>
  );
  const drawn = glyph.transform ? <g transform={glyph.transform}>{geometry}</g> : geometry;
  return (
    <svg
      viewBox={glyph.viewBox}
      className={className}
      fill="currentColor"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
    >
      {glyph.inset ? <g transform={insetTransform(glyph.viewBox, glyph.inset)}>{drawn}</g> : drawn}
    </svg>
  );
}

/** A scale-about-centre matrix for `Glyph.inset`: shrinks by `inset` (a
 *  fraction of the box) about the viewBox's own centre, in viewBox space. */
function insetTransform(viewBox: string, inset: number): string {
  const [minX, minY, width, height] = viewBox.split(/\s+/).map(Number);
  const cx = minX + width / 2;
  const cy = minY + height / 2;
  const scale = 1 - inset;
  return `translate(${cx} ${cy}) scale(${scale}) translate(${-cx} ${-cy})`;
}
